"""Write the final report only after successful real runs, offline audit and final checks."""
from pathlib import Path
import json

root=Path('out/engine3d/phase22')
def read(name):return json.loads((root/'analysis'/name).read_text(encoding='utf-8'))
status=read('final-status.json');assert status['phase22Complete']
checks=read('checks.json');assert len(checks)==16 and all(c['exitCode']==0 for c in checks)
runs=read('live-runs.json');assert len(runs)==2 and all(r['exitCode']==0 for r in runs)
m=read('mandatory-answers.json');comparison=read('benchmark-comparison.json');metrics=read('metrics.json');replay=read('replay-verification.json');integrity=read('integrity.json');anti=read('anti-hardcode.json')
c=comparison['phase22'];p=comparison['secondPhase22'];g=m['realWorldGates']
def table(headers,rows):
    def cell(x):return str(x).replace('|','\\|').replace('\n',' ')
    return '| '+' | '.join(headers)+' |\n|'+'|'.join(['---']*len(headers))+'|\n'+'\n'.join('| '+' | '.join(map(cell,row))+' |' for row in rows)
def link(file):return '['+file+'](out/engine3d/phase22/'+file+')'
sections=[]
def section(name,body):sections.append('## '+name+'\n\n'+body.strip()+'\n')

section('Objective',f'''Concluir a implementação e a validação da Research v3 a partir do checkpoint oficial, preservando factual safety e compatibilidade. **PHASE22 COMPLETE: YES — implementation gate PASS.** Isso não significa pesquisa pronta: Cold está **{c['result']}**, ranking **{m['ranking']}**, **{m['eligible']}/5** elegíveis. Nenhum MP4 foi produzido. Os gates reais são reportados separadamente abaixo.''')
section('Starting State','''Branch `main`, HEAD `686d08d69889b291f31b12fde117977d85c0b291`, árvore inicialmente limpa e checkpoint confirmado em `origin/main`. Base Phase21 `838bc9c`. A v3 existia como implementação parcial, sem suíte própria nem benchmark real validado. Autonomia inicial LEVEL4C. O HEAD permanece no checkpoint: sem commit/push nesta continuação.''')
section('Checkpoint Handoff','''Lidos `PHASE22_HANDOFF_INCOMPLETE.md`, `CLONAI_HANDOFF.md`, `PHASE21_REPORT.md`, o diff completo entre a base Phase21 e o checkpoint e os helpers originais em `tools/phase22-checkpoint`. A continuação aproveitou os módulos existentes. O handoff incompleto foi preservado como histórico; este documento registra o resultado final.

Foi criada a suíte antes das correções e dos benchmarks. Falhas incrementais expuseram ambiguidade de subjects, deduplicação indevida de evidence em empate, provenance JSON-LD apontando para o bloco errado, conteúdo HTML ignorado interpretado como registro, fingerprint de grafo dependente da ordem, tarefas de corroboração sem limite individual e replay que não validava o conteúdo armazenado da pool. As correções têm regressões fictícias.''')
section('Architecture','''Fluxo de produção preservado: Codex → DirectorPlan.json → Engine3D → Three/R3F → Remotion → edge-tts → MP4. A camada anterior recebe ResearchRequest → descoberta/fetch seguro → snapshots → EvidencePack → GROUNDED_ONLY → preflight. Esta fase altera pesquisa, revisão e auditoria, sem expandir Engine3D, Writer, render ou assets.''')
section('Research v3','''Opt-in explícito `sourcePolicy.researchVersion: 3`. Módulos reaproveitados: `context.ts`, `records.ts`, `entities.ts`, `authority.ts`, `v3-extract.ts`, `v3.ts`, `similarity.ts` e `web/v3.ts`. Novos: suíte v3, output v3, auditoria offline, inputs portáveis e helpers de reprodução.

Correções finais adicionais: médias de extremos abstêm em vez de virar mínimo registrado; snapshots com o mesmo final URL+hash são admitidos uma vez, mantendo todas as tentativas. A deduplicação só muda a admissão v3 e não cria origens. O parser antigo permanece compatível nas observações históricas, inclusive após a guarda estatística compartilhada.''')
section('Independent Discovery','''MediaWiki, Wikidata, OpenAlex e Crossref usam endpoints públicos gratuitos. Links de publisher e referências passam pelo mesmo cliente seguro. A independência da descoberta é registrada separadamente da independência da evidência. Um artigo descoberto via corpus independente pode continuar derivado da fonte citada.

''' +link('review/independent-discovery.md')+'; estratégias, falhas e métricas em '+link('analysis/metrics.json')+'.')
section('Candidate Entity Pool',f'''Cold: **{m['coldCandidates']} candidatos relevantes com evidência de fonte**, {m['rawSourceBackedPlaces']} place candidates brutos, {m['observationSites']} observation sites e {m['searchOnly']} títulos apenas de busca. Candidatos relevantes: {', '.join(m['sourceBackedCandidateNames'])}. Candidato não significa settlement comprovado nem elegibilidade. A pool bruta ainda contém ruído de rótulos/documentos, registrado na revisão e excluído dos itens finais.

Pool determinística, com proveniência, cobertura, aliases e prioridade: '''+link('review/candidate-entity-pool.md')+'.')
section('Query Planning v3','''Queries têm `purpose`, `derivedFrom`, `targetGap`, entidade/fato e origens excluídas quando aplicável. Lacunas de métrica, população, fonte oficial, alias e corroboração recebem propósitos distintos. Os inputs finais não contêm entidades, temperaturas, publishers, URLs de fontes nem ranking esperado. O benchmark mantém o tópico integral e as constraints da Phase21.''')
section('Document Context',f'''O resolvedor lê headings de dados, label/value e metadados com spans exatos antes da herança para tabelas. URL pode ser pista, nunca fato. O benchmark produziu **{len(m['officialContextEvidence'])} EVs oficiais/institucionais com contexto herdado**; os IDs, trechos e offsets estão em {link('analysis/mandatory-answers.json')} e {link('review/document-context.md')}.''')
section('Subject Resolution','''Subjects ausentes ou concorrentes resultam em abstention, sem escolher o primeiro nome. Vários campos de localização preservam a ambiguidade. Descritor parentético de estação não destrói o nome. O kind STATION é mantido quando sustentado pelo contexto; spans de label, valor e contexto permanecem separados.''')
section('Context-aware Tables','''TH amplo pode ser section label em vez de segundo header. Labels em TD são interpretados; coluna anual e janela de observação não se confundem com valor mensal ou data do evento. Lowest maximum, day-count, time-of-day mean e médias de extremos não viram MINIMUM_RECORDED. Average daily minimum permanece qualificador separado.''')
section('Station/Location Resolution','''Stations e settlements continuam nós e fatos distintos. `SAME_ENTITY_ONLY` não transfere medição. O input v3 permite `SOURCED_OBSERVATION_SITE`, exigindo relação explícita source-backed. NEAR não é equivalência. Quando uma relação permitida abastece um item, o label é o settlement e `measurementFactId` mantém o fato da estação. População permanente continua sendo uma exigência independente.

'''+link('review/station-resolution.md')+'; política preservada em '+link('analysis/policy-preservation.json')+'.')
section('Entity Graph','''IDs, ordenação e fingerprint independem da ordem de entrada, inclusive variantes de caixa nos nomes. Arestas guardam fonte, motivo e span quando aplicável. Relações desconhecidas não provam independência. Review: '''+link('review/entity-graph.md')+'.')
section('Alias/Transliteration','''AlternateName de JSON-LD gera SUPPORTED_ALIAS; similaridade de transliteração gera CANDIDATE_ALIAS. Nenhum deles funde entidades. Apenas CONFIRMED com linguagem explícita e suporte permitido pode participar da resolução; rejeições de identidade permanecem veto.''')
section('Semi-Structured Records','''Registros de campos TD, div e parágrafos rotulados preservam heading, campo, valor, data, semântica e provenance. Blocos script/style/nav/aside/iframe/noscript e comentários são mascarados sem deslocar offsets. Record extraction não usa snippets ou conhecimento interno. Review: '''+link('review/primary-records.md')+'.')
section('Multi-Subject Records','''Subjects alternativos/ambíguos, inclusive separados por line breaks, não recebem fatos individuais. Empates explicitamente compartilhados podem gerar um fato por subject, com evidence ID distinto e sharedRecordId. Ausência de separador não autoriza inventar uma entidade conjunta.''')
section('Publisher Identity','''Identidade vem de sinais explícitos no snapshot, como organização declarada em JSON-LD, meta e copyright. Cada sinal mantém o bloco/span que realmente o declara. Meta em comentário não estabelece publisher. Review: '''+link('review/publisher-authority.md')+'.')
section('Authority Assessment','''TLD isolado não confere autoridade. HIGH exige identidade e compatibilidade com o domínio factual. PublisherIdentity, authority, SourceQuality e independência são objetos distintos. A avaliação é heurística sobre declarações públicas, não autenticação universal nem garantia de verdade.''')
section('Primary Source Classification',f'''Cold aceitou {c['primarySources']} fontes primárias e {c['institutionalSources']} institucionais/acadêmicas pela classificação efetiva. A classe originalmente declarada continua em `pack.sources`; a classe derivada v3 é usada na avaliação/grounding e fica auditável. REFERENCE não é promovida a oficial. As exceções de origem única com autoridade HIGH são exatamente as da Phase21; quorum padrão continua 2.''')
section('Corroboration Tasks','''Tarefas registram factKey, entidade, métrica, qualifier, origens conhecidas/excluídas, queries por provider, prioridade, budget e status. Uma tentativa REFERENCE_DERIVED não esgota tarefa de descoberta independente. O limite por tarefa é aplicado a fetches efetivos. Review: '''+link('review/corroboration.md')+'.')
section('Independence v3',f'''SourceGraph, grupos de origem e raízes por fato continuam controlando o quorum. Corpos idênticos, domínio comum, arquivos do mesmo original, near-copy e dependência declarada não criam origens extras. Cold terminou com **{c['corroborated']} CORROBORATED**, apesar da diversidade de caminhos de descoberta. Publisher following não é corroboração independente.''')
section('Near-Copy Detection','''Jaccard de shingles de quatro palavras, threshold 0,6 e tamanho mínimo, aplicado a prose. Tabelas estruturadas ficam fora dessa comparação. É uma aproximação conservadora; textos curtos e paráfrases podem escapar e documentos parecidos podem ser agrupados em excesso.''')
section('Large Source Handling','''CSV/TSV pode ser baixado até o teto transitório configurado (8 MiB nos inputs), sempre dentro do total. Só header + linhas com termos de candidatos são retidos. fullBytes/fullSha256, regra, termos e contagem de linhas ficam em metadata.partial. Offsets de evidence referem-se ao snapshot parcial retido, não ao payload completo. Fórmulas não são executadas nem tratadas como números. Mock CSV e TSV verificam o fluxo, hash e limites. Não há truncamento genérico de HTML grande nem alegação de êxito real de large ingestion sem partial source registrado.''')
section('Language/JS/PDF Diagnostics','''EN/PT são os idiomas de extração suportados. Snapshot com idioma explicitamente não suportado pode permanecer REJECT no grafo, sem facts. HTML estático compacto com dados é aceito; empty HTML, necessidade de JS e anti-bot recebem diagnósticos separados. PDF é referência não ingerida: os diagnósticos TEXT_REQUIRED/TABLE_REQUIRED/SCANNED_UNKNOWN são pistas do contexto do link, não inspeção do PDF. Nenhum bypass ou execução de JS.''')
section('Research Loop v3','''R0 broad discovery; R1 expansão; R2 verificação; R3 referências e links de publisher; R4 corroboração independente; R5 repetição limitada das lacunas. R5 não é um enum de provider separado. Mock testa caminho com ranking válido e caminho bloqueado sem quinto inventado. Limites globais, estágios, domínios, timeout, bytes e tarefas permanecem ativos. Os dois benchmarks foram executados via CLI live, sem fixture providers.''')
section('Task Priority','''Value of information favorece entidade próxima do quorum, depois lacunas acionáveis de métrica/presença e descoberta. Empates têm ordenação determinística. A priorização melhora a ordem de trabalho; não prova disponibilidade de fontes independentes.''')
section('Cold Places Benchmark',f'''Tópico: “Os cinco lugares mais frios onde pessoas vivem permanentemente.” TEMPERATURE + MINIMUM_RECORDED + PERMANENT_POPULATION, quorum 2 e exceções HIGH preservadas. Scope SESSION_CANDIDATES; nenhum superlativo mundial exaustivo estabelecido.

Live final: {c['queries']} queries, {c['searchResults']} resultados, {c['acceptedSources']} fontes aceitas, {c['supported']} SUPPORTED, {c['corroborated']} CORROBORATED e {c['conflicted']} CONFLICTED. Apenas {m['supportedMinimumRecorded']} dos fatos admitidos é MINIMUM_RECORDED; os demais qualificadores não contam para o ranking. Writer: {c['writer']}.

'''+table(['Gate','Resultado','Evidência'],[[key,'PASS' if value['passed'] else 'FAIL',value['detail']] for key,value in g.items()])+'''

R3 é estrito: compara o mesmo ID de fato canônico com Phase21 e v2 sobre os snapshots atuais. Novas identidades de estação não são apresentadas como transição do antigo fato do settlement. O runtime R3_ADMITTED_FACT indica apenas existência de fato admitido; o resultado oficial desta fase usa a auditoria estrita.

Tentativas anteriores foram preservadas em `attempts/`: a primeira continha uma média de extremos classificada como mínimo e seu replay corretamente falhou após a correção. Uma nova coleta expôs duplicação de final URL/hash e falhou antes de salvar sessão final. Regressões foram adicionadas, guards corrigidos e ambas as coletas refeitas. Somente os logs finais abaixo sustentam os números deste relatório.''')
section('Cold Entity Eligibility',f'''**{m['eligible']}/5; {m['ranking']}**. Não foram inventados itens nem substituídos mínimos por médias. O principal bloqueio do candidato próximo da elegibilidade é o suporte independente para população permanente; outros candidatos ainda carecem de medição/presença compatíveis. Estações isoladas não são assentamentos.

'''+table(['Entidade','Elegível','Diagnóstico'],[[e['entity'],e['eligible'],e['reason']] for e in m['eligibility']])+'\n\nChecklist por entidade: '+link('review/cold-eligibility.md')+'.')
section('Phase20/21/22 Comparison',table(['Fase','Fontes','Domínios fetched','Primárias','SUPPORTED','CORROBORATED','Elegíveis','Resultado'],[[name,row['acceptedSources'],row['domainsFetched'],row['primarySources'],row['supported'],row['corroborated'],row['eligible'],row['result']] for name,row in comparison.items() if name in ['phase20','phase21','phase22']])+'''

São observações live distintas, com orçamento, tempo e disponibilidade de rede próprios. Não é um teste A/B de corpus idêntico. O contrafactual v2 sobre snapshots v3 está identificado como análise offline separada e não como benchmark real. Dados: '''+link('analysis/benchmark-comparison.json')+'.')
section('Second Real Benchmark',f'''Reutilizado o tópico de população recenseada da Phase21. Live final: {p['queries']} queries, {p['acceptedSources']} fontes, {p['facts']} GroundedFacts candidatos, {p['supported']} SUPPORTED, {p['corroborated']} CORROBORATED; **{p['result']}**, Writer {p['writer']}. Quantidades de população não implicam população permanente. Uma única origem e lacunas de fontes/formatos continuam insuficientes para admissão. A generalização do parser foi exercitada, mas a readiness real não foi demonstrada. Writer v2 não foi implementado; QUANTITY realization permanece limitação posterior e não foi contornada.''')
section('Source Gaps','''Contagens finais por benchmark:

'''+table(['Benchmark','Código','Quantidade'],[[label,code,n] for label,row in [('Cold',c),('Population',p)] for code,n in row['gaps'].items() if code not in ['EVIDENCE_EXTRACTION_GAP','ENTITY_RESOLUTION_GAP','FACT_CONFLICT']])+'''

Disponibilidade, robots, HTTP, idioma, formato e descoberta são lacunas diferentes de falta de corroboração. Os diagnósticos originais permanecem nas sessões e JSONs `source-gaps/`. Não houve scraping de Google/Bing nem bypass de challenge.''')
section('Extraction Gaps','''Documentos baixados podem falhar por contexto ambíguo, subject coletivo, qualifier/estrutura não suportada ou ausência de relação estação/local. Falsos candidatos de labels ainda aparecem como ruído na pool bruta. Não houve parser universal ou imputação. JSONs `extraction-gaps/` e reviews preservam cada caso; fatos conflicted permanecem não utilizáveis.''')
section('Replay',f'''**PASS, ZERO NETWORK ({replay['networkCalls']} chamadas).** As duas sessões v3 finais reconstroem pool/tasks, contextos, records, EntityGraph, publishers/authority, SourceGraph, EVs, GroundedFacts, ranking e writer, com fingerprints iguais. Script/plano são N/A quando o writer não os produz; não se alega replay de um MP4 inexistente. Também foram rederivados nove packs históricos e replayadas quatro sessões Phase20/21.

HTTP/request/get, HTTPS/request/get, fetch, DNS e transport foram substituídos por falha contadora na auditoria. Mismatch de sessão, conteúdo da pool e fingerprints gera erro. Prova: '''+link('analysis/replay-verification.json')+'.')
section('Security','''PASS nos testes e na auditoria. Preservados SSRF público-only, todas as respostas DNS públicas, socket pinning, redirects revalidados, robots, MIME/charset, limites de streaming/tamanho/tempo/query/fetch e budgets individuais. Publisher links usam a mesma fronteira. Nenhum PDF, fórmula, HTML ativo ou JS é executado. Conteúdo externo em reviews é escapado. Segurança de transporte não certifica autenticidade do publisher nem a verdade de uma afirmação. '''+link('analysis/security.json')+'.')
section('Anti-hardcode',f'''**PASS**, {anti['scannedFiles']} arquivos examinados e zero BLOCKER. Scan cobre subjects, valores, URLs/domínios finais e referências, publisher names, station names e ordem do ranking. Regras/endpoints genéricos de providers, coincidências pré-checkpoint, documentação e quantidades fictícias de testes são classificados explicitamente, com todos os achados preservados. Snapshots/cache/sessões são outputs adquiridos, nunca seeds. '''+link('analysis/anti-hardcode.json')+'.')
section('Determinism','''Mesmo snapshot/policy gera os mesmos fingerprints; ordenação reversa e variantes de caixa têm regressões. Relógio/rede só pertencem à aquisição, não ao render. Replays comparam conteúdo reconstruído e fingerprints, sem copiar conclusões como fallback. Nenhum relógio ou aleatoriedade foi adicionado ao pipeline de render.''')
section('Performance',table(['Benchmark','Wall live ms','Bytes rede','Replay CPU/wall ms'],[[label,metrics[key]['performance']['wallMs'],metrics[key]['bytes'],metrics[key]['performance']['replayMs']] for label,key in [('Cold','real-cold-places-v3'),('Population','real-population-census-v3')]])+'''

Network/fetch/search têm tempos próprios e parcialmente sobrepostos; não são somados ao wall total. Replays foram medidos isoladamente sem rede. Rebuilds de packs e comparação de prose têm custo relevante nos budgets máximos; não houve otimização que alterasse factual safety. Métricas e tempos por comando em '''+link('analysis/metrics.json')+' e '+link('analysis/checks.json')+'.')
section('Tests',f'''**{status['testsV3']['pass']}/{status['testsV3']['tests']} v3 PASS; 764 testes únicos na suíte completa; 16/16 comandos obrigatórios PASS.** 688 testes anteriores + 76 v3. Research v1/web/v2/v3 totalizam 278 testes; as execuções individuais abaixo repetem testes da suíte completa, não aumentam a contagem única. Fixtures v3 usam identidades fictícias e providers mockados, sem rede.

'''+table(['Comando','Exit','Testes','Segundos'],[[x['command'],x['exitCode'],x['counts'].get('tests','—'),x['elapsedSeconds']] for x in checks])+'''

Coverage inclui as 47 capacidades solicitadas, bugs do handoff, scripts/comments ignorados, provenance do bloco correto, guardas estatísticas e duplicação de snapshot via redirect. Testes históricos não foram editados. Helpers originais preservados.''')
section('Registry',f'''Engine3D **{integrity['registry']['Engine3D']}** / SFX **{integrity['registry']['SFX']}** / VISUAL **{integrity['registry']['VISUAL']}**. Catálogo regenerado/validado pelo comando obrigatório. Nenhum asset ou capability novo. Os {len(integrity['oldVideosUnchanged'])} MP4s históricos conservam seus SHA-256. package-lock e render engine não mudaram. '''+link('analysis/integrity.json')+'.')
section('Compatibility','''V1/v2 continuam opt-out da v3. Nove packs e quatro sessões históricas rederivam/replayam de forma idêntica; schemas e writer/render legados mantidos. A alteração compartilhada de vocabulário rejeita uma classe estatística inválida sem alterar os artefatos históricos verificados. Dependências e versões intactas. Nenhum commit/push, remote novo, reset, clean ou force push nesta fase.''')
section('Limitations','''Sem descoberta exaustiva da web, confirmação universal de identidade, parser de PDF, renderer JS, tradução ampla, full-text de qualquer paper ou large-HTML truncation. Domínio registrável e near-copy são heurísticas. Records/semântica se limitam a padrões literais testados. A pool pode reter ruído. Os benchmarks não demonstraram corroboração independente suficiente nem readiness de roteiro; Writer QUANTITY realization é uma limitação posterior. Dados volumosos de `out/` permanecem locais/ignorados pelo Git e devem ser copiados separadamente se necessários em outro PC.''')
section('Honest Assessment',f'''A Phase22 está concluída como implementação, hardening, testes, duas execuções reais e auditoria. R1/R2 demonstram candidatos e extração oficial por contexto; R3/R4/R5/R6 seguem conforme os resultados estritos acima. O objetivo STRONG (um Cold item elegível) **não foi atingido** com {m['eligible']}/5. Cinco SUPPORTED não significam cinco locais elegíveis, e médias não são substitutos para mínimos. Não foi gerado roteiro ou vídeo para preencher lacunas.''')
section('Autonomy Level','''**LEVEL4C mantido.** Há capacidade nova demonstrada de extração por contexto e publisher assessment, mas os benchmarks ainda exigem fontes independentes e não chegam à readiness. Não houve promoção automática para LEVEL4C+ ou LEVEL5.''')
section('Next Recommendation','''Uma única recomendação para Phase23: melhorar a aquisição e a corroboração independente orientada às lacunas de população permanente e mínimo registrado, com provenance por fato e o mesmo quorum. Não iniciar Writer v2, assets ou render para contornar research incompleta. **Phase23 não iniciada. PARAR aqui.**

Artefatos principais: '''+link('analysis/final-status.json')+', '+link('analysis/mandatory-answers.json')+', '+link('analysis/replay-verification.json')+', '+link('analysis/checks.json')+'. As nove reviews consolidadas ficam em `out/engine3d/phase22/review/`; snapshots, fontes, EvidencePack, source/entity graphs, contexts, records, publishers, authority, pools, tasks, eligibility e fingerprints permanecem nos diretórios correspondentes.')

assert len(sections)==44,len(sections)
Path('PHASE22_REPORT.md').write_text('# Phase 22 — Research v3 — Final report\n\nData: 2026-10-28. Continuação do checkpoint oficial; resultado final da fase.\n\n'+'\n'.join(sections),encoding='utf-8')
print(json.dumps({'report':'PHASE22_REPORT.md','sections':len(sections),'phase22Complete':True,'researchReady':c['result']=='REAL_RESEARCH_READY','gates':g},ensure_ascii=False))
